R = {"title": "Sales", "columns": ["region", "units"], "rows": [["north", 12], ["south", 7], ["east", 3]]}
E = {"title": "T", "columns": ["a"], "rows": []}
for f in available_formats():
    print(f"--- {f} (max_rows=1)"); print(repr(render(R, f, max_rows=1)))
    print(f"--- {f} (empty)"); print(repr(render(E, f)))
print(render_many([R, R], "text", max_rows=0))
try: render(R, "text", max_rows=-1)
except ValueError as e: print("ValueError:", e)
class Upper(BaseRenderer):
    name = "upper"
    def render_rows(self, report): return "\n".join(" ".join(self.cells(r)).upper() for r in report["rows"])
print(available_formats(), repr(render(R, "upper", max_rows=2)))
